                asset.uploadId = payload.upload_id;
                asset.uploadToken = payload.upload_token;
                asset.streamKeyHex = payload.stream_key_hex || '';
                asset.streamIvSeedHex = payload.stream_iv_seed_hex || '';
                asset.modulusM = payload.modulus_M || 1;
